#!/bin/bash
# LinkPro — อัปเดตระบบ (server.js + หน้าเว็บทั้งหมด) สำรองไฟล์เดิมก่อน และย้อนกลับอัตโนมัติถ้าเปิดไม่ขึ้น
set -eu
[ "$(id -u)" = 0 ] || { echo "กรุณารันด้วย sudo"; exit 1; }
APP=/opt/linkpro/app
UNIT=/etc/systemd/system/linkpro.service
BAK=/opt/linkpro/backup-$(date +%Y%m%d-%H%M%S)
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
NODE=$(sed -n 's/^ExecStart=\([^ ]*\) .*/\1/p' "$UNIT" 2>/dev/null | head -1)
[ -x "${NODE:-}" ] || NODE=$(command -v node)
echo "1/5 แตกไฟล์ใหม่"
echo '' | base64 -d | tar -xJ -C "$TMP"
echo "2/5 ตรวจโค้ด"
"$NODE" --check "$TMP/server.js"
echo "3/5 สำรองไฟล์เดิมไว้ที่ $BAK"
mkdir -p "$BAK"
cp -a "$APP/server.js" "$APP/public" "$BAK/"
echo "4/5 ติดตั้งไฟล์ใหม่และรีสตาร์ท"
cp -a "$TMP/." "$APP/"
chown -R linkpro:linkpro "$APP"
systemctl restart linkpro
echo "5/5 ตรวจว่าเว็บทำงาน"
ok=0
for i in $(seq 1 15); do
  sleep 1
  if curl -fsS -o /dev/null http://127.0.0.1:3100/apply && curl -fsS -o /dev/null http://127.0.0.1:3100/api/public/jobs; then ok=1; break; fi
done
if [ "$ok" = 1 ]; then
  echo "✅ อัปเดตเรียบร้อย — เว็บทำงานปกติ (ไฟล์เดิมสำรองไว้ที่ $BAK)"
else
  echo "❌ เว็บไม่ตอบสนอง กำลังย้อนกลับเป็นเวอร์ชันเดิม..."
  journalctl -u linkpro -n 20 --no-pager || true
  rm -rf "$APP/public"
  cp -a "$BAK/server.js" "$BAK/public" "$APP/"
  chown -R linkpro:linkpro "$APP"
  systemctl restart linkpro
  echo "ย้อนกลับแล้ว เว็บใช้เวอร์ชันเดิม กรุณาส่งข้อความด้านบนให้ Claude ดู"
  exit 1
fi
